import assert from "node:assert/strict";
import { EPOCH_MS, makeTickets, ticketAged } from "./support/tickets.mjs";

/**
 * FROZEN behaviour scenarios for `src/triage.mjs`. Do not edit this file — it is the evidence the repair is graded
 * on, and the verifier checks its content digest on every run.
 *
 * Each scenario drives the module's public API over a range of inputs rather than one magic value, so a defect
 * cannot be papered over by special-casing whatever the assertion happens to look at.
 */

const load = () => import("../src/triage.mjs");

export const scenarios = [
	{
		id: "oldest-open-returns-the-requested-count",
		title: "oldestOpen(tickets, n) returns exactly the n oldest open tickets, oldest first",
		async check() {
			const { oldestOpen } = await load();
			for (const seed of [11, 4242, 90210]) {
				const tickets = makeTickets(seed, 24);
				const open = tickets
					.filter((ticket) => ticket.status === "open")
					.sort((left, right) => left.createdAt - right.createdAt);
				for (let count = 1; count <= open.length; count += 1) {
					const picked = oldestOpen(tickets, count);
					assert.equal(
						picked.length,
						count,
						`seed ${seed}: oldestOpen(tickets, ${count}) returned ${picked.length} tickets, not ${count}`,
					);
					assert.deepEqual(
						picked.map((ticket) => ticket.id),
						open.slice(0, count).map((ticket) => ticket.id),
						`seed ${seed}: oldestOpen(tickets, ${count}) is not the ${count} oldest open tickets in age order`,
					);
				}
			}
		},
	},
	{
		id: "oldest-open-handles-the-edges",
		title: "asking for none returns none, asking for more than exist returns every open ticket",
		async check() {
			const { oldestOpen } = await load();
			for (const seed of [7, 555]) {
				const tickets = makeTickets(seed, 18);
				const open = tickets.filter((ticket) => ticket.status === "open");
				assert.equal(
					oldestOpen(tickets, 0).length,
					0,
					`seed ${seed}: oldestOpen(tickets, 0) must return nothing`,
				);
				const everything = oldestOpen(tickets, open.length + 5);
				assert.equal(
					everything.length,
					open.length,
					`seed ${seed}: asking for more tickets than exist must return all ${open.length} open ones`,
				);
				assert.deepEqual(
					everything.filter((ticket) => ticket.status !== "open").map((ticket) => ticket.id),
					[],
					`seed ${seed}: closed tickets must never appear in the open queue`,
				);
			}
		},
	},
	{
		id: "sla-breach-is-inclusive-at-the-limit",
		title: "a ticket that has waited exactly its SLA has breached it",
		async check() {
			const { breachedTickets, isBreached } = await load();
			for (const sla of [1, 15, 60, 240, 1440]) {
				assert.equal(isBreached(sla - 1, sla), false, `${sla - 1} minutes is inside a ${sla}-minute SLA`);
				assert.equal(isBreached(sla, sla), true, `exactly ${sla} minutes has used up a ${sla}-minute SLA`);
				assert.equal(isBreached(sla + 1, sla), true, `${sla + 1} minutes is past a ${sla}-minute SLA`);
			}
			const sla = 120;
			const tickets = [ticketAged(sla - 1), ticketAged(sla), ticketAged(sla + 1)];
			assert.deepEqual(
				breachedTickets(tickets, EPOCH_MS, sla).map((ticket) => ticket.id),
				[`AGE-${sla}`, `AGE-${sla + 1}`],
				`the ${sla}-minute-old ticket has breached a ${sla}-minute SLA and must be listed`,
			);
		},
	},
	{
		id: "escalation-threshold-defaults-to-sixty-minutes",
		title: "with no options, queueFor escalates at the desk default of 60 minutes and not before",
		async check() {
			const { DEFAULT_ESCALATE_AFTER_MINUTES, queueFor } = await load();
			const threshold = 60;
			assert.equal(
				DEFAULT_ESCALATE_AFTER_MINUTES,
				threshold,
				"the desk default is 60 minutes and the exported constant must say so",
			);
			for (const age of [0, 1, Math.floor(threshold / 2), threshold - 1]) {
				assert.equal(
					queueFor(ticketAged(age), EPOCH_MS),
					"standard",
					`a ${age}-minute-old ticket is inside the ${threshold}-minute default and belongs in the standard queue`,
				);
			}
			for (const age of [threshold, threshold + 1, threshold * 10]) {
				assert.equal(
					queueFor(ticketAged(age), EPOCH_MS),
					"escalated",
					`a ${age}-minute-old ticket has reached the ${threshold}-minute default and must be escalated`,
				);
			}
		},
	},
	{
		id: "escalation-honours-an-explicit-threshold",
		title: "an explicit escalateAfterMinutes wins, and it too fires at the limit",
		async check() {
			const { queueFor } = await load();
			for (const threshold of [5, 45, 90, 720]) {
				const options = { escalateAfterMinutes: threshold };
				assert.equal(
					queueFor(ticketAged(threshold - 1), EPOCH_MS, options),
					"standard",
					`${threshold - 1} minutes is inside an explicit ${threshold}-minute threshold`,
				);
				assert.equal(
					queueFor(ticketAged(threshold), EPOCH_MS, options),
					"escalated",
					`exactly ${threshold} minutes reaches an explicit ${threshold}-minute threshold`,
				);
				assert.equal(
					queueFor(ticketAged(threshold + 30), EPOCH_MS, options),
					"escalated",
					`${threshold + 30} minutes is past an explicit ${threshold}-minute threshold`,
				);
			}
		},
	},
];
